// Independent auditor PLAY-03 committed-projection cache and reference-command probe (real test PostgreSQL).
import assert from 'node:assert/strict';
import { createHash, randomBytes } from 'node:crypto';
import { service, fixtureId, command, open, counts, cleanup, using } from './apps/match-service/tests/fixtures.mjs';
import { createEngineExecutor } from './apps/match-service/dist/engine-executor.js';
import { restorePrivateMatch } from './packages/engine-adapter/dist/index.js';
import { canonical } from './packages/engine-adapter/dist/replay.js';
import { encodeViewerProjection } from './packages/contracts/dist/index.js';

const digest = a => createHash('sha256').update('private-match-checkpoint-v1\0').update(a).digest('hex');
const enc = v => encodeViewerProjection(v);
const engine = createEngineExecutor(); let projects = 0;
const counting = { execute: job => engine.execute(job), project: job => { projects++; return engine.project(job); }, close: () => engine.close() };
const id = fixtureId(), s = service(undefined, { executor: counting }), s2 = service();
let s3;
const R = { coalesced: {}, tamper: 0, refs: {}, timing: { coldMs: [], warmMs: [], submitMs: [] } };
const stored = () => using('match', async c => (await c.query('SELECT checkpoint,checkpoint_digest,engine_identity,state_version FROM match.matches WHERE match_id=$1', [id])).rows[0]);
const project = (row, playerId) => { const pm = restorePrivateMatch({ archive: row.checkpoint, digest: row.checkpoint_digest }, id); try { return pm.project({ kind: 'participant', playerId }); } finally { pm.dispose(); } };
const hand = (v, p) => v.players.find(x => x.playerId === p).zones.find(z => z.kind === 'hand');
const setColumns = v => using('match', c => c.query('UPDATE match.matches SET checkpoint=$1,checkpoint_digest=$2 WHERE match_id=$3', [v.checkpoint, v.checkpoint_digest, id]));
async function timed(list, fn) { const t = performance.now(); const r = await fn(); list.push(Math.round(performance.now() - t)); return r; }
const refCommand = (cid, version, move, input) => ({ matchId: id, commandId: cid, expectedVersion: version, move, input });
try {
  await open(s2, id);
  let row = await stored();
  // Cold read executes one projection; a 48-way burst of the same viewer/version is served from the one coalesced entry.
  const first = await timed(R.timing.coldMs, () => s.view('p1', { matchId: id })); assert.equal(projects, 1); assert.equal(enc(first), enc(project(row, 'p1')));
  const burst = await Promise.all(Array.from({ length: 48 }, () => s.view('p1', { matchId: id })));
  assert.ok(burst.every(v => enc(v) === enc(first))); assert.equal(projects, 1); R.coalesced.warm48 = { served: 48, projections: 0 };
  await timed(R.timing.warmMs, () => s.view('p1', { matchId: id }));
  // Viewer is part of the key: mixed burst adds exactly one projection for the other player, and the payloads never cross.
  const mixed = await Promise.all(Array.from({ length: 48 }, (_, i) => s.view(i % 2 ? 'p2' : 'p1', { matchId: id })));
  assert.equal(projects, 2); for (const [i, v] of mixed.entries()) assert.equal(enc(v), enc(project(row, i % 2 ? 'p2' : 'p1')));
  assert.notEqual(enc(mixed[0]), enc(mixed[1])); assert.deepEqual(hand(mixed[1], 'p1').cards, []); assert.deepEqual(hand(mixed[0], 'p2').cards, []);
  // Authorization precedes the cache: outsiders and malformed requests never see a cached payload.
  for (const actor of ['outsider', 'p3']) await assert.rejects(s.view(actor, { matchId: id }), e => e?.code === 'FORBIDDEN');
  await assert.rejects(s.view('p1', { matchId: id, viewer: 'p2' }), e => e?.code === 'INVALID_REQUEST');
  // A commit through a different service instance is visible at once (no stale cached version).
  const ref = hand(first, 'p1').cards[0].ref, v3 = Number(row.state_version);
  const ink = await timed(R.timing.submitMs, () => s2.submitRefs('p1', refCommand('ink-1', v3, 'putCardIntoInkwell', { cardId: ref })));
  assert.equal(ink.receipt.outcome, 'accepted'); assert.equal(ink.duplicate, false);
  row = await stored(); const next = await s.view('p1', { matchId: id }); assert.equal(next.stateVersion, v3 + 1); assert.equal(enc(next), enc(project(row, 'p1'))); assert.equal(projects, 3);
  // Cold burst after the commit: one projection serves all 48 (the PLAY-02 audit measured 34 served / 14 refused without a cache).
  const pass = await s2.submit('p1', command(id, 'pass-1', v3 + 1, 'passTurn', {})); assert.equal(pass.receipt.outcome, 'accepted'); row = await stored();
  const before48 = projects, cold = await Promise.allSettled(Array.from({ length: 48 }, () => s.view('p2', { matchId: id })));
  assert.ok(cold.every(r => r.status === 'fulfilled' && enc(r.value) === enc(project(row, 'p2')))); assert.equal(projects - before48, 1); R.coalesced.cold48 = { served: 48, projections: 1 };
  // Beyond 64 concurrent reads the service refuses with a fixed code; the rest are served.
  const p2 = await s2.view('p2', { matchId: id }), ink2 = await s2.submitRefs('p2', refCommand('ink-2', v3 + 2, 'putCardIntoInkwell', { cardId: hand(p2, 'p2').cards[0].ref })); assert.equal(ink2.receipt.outcome, 'accepted'); row = await stored();
  const over = await Promise.allSettled(Array.from({ length: 80 }, () => s.view('p1', { matchId: id })));
  const served = over.filter(r => r.status === 'fulfilled'), refused = over.filter(r => r.status === 'rejected');
  assert.ok(served.every(r => enc(r.value) === enc(project(row, 'p1')))); assert.ok(refused.every(r => r.reason?.code === 'UNAVAILABLE')); assert.ok(served.length >= 64);
  R.coalesced.over80 = { served: served.length, refused: refused.length };
  // The cache key binds the exact stored bytes: forged (re-digested) checkpoints fail closed instead of hitting the cached view; restoring the bytes hits again.
  const good = await s.view('p1', { matchId: id }), countBefore = projects, envelope = JSON.parse(row.checkpoint);
  const forge = mutate => { const e = structuredClone(envelope); mutate(e); const archive = canonical(e); return { checkpoint: archive, checkpoint_digest: digest(archive) }; };
  for (const f of [forge(e => { e.transcript.seed = randomBytes(32).toString('hex'); }), forge(e => { e.transcript.final.status.winner = 'p2'; e.transcript.final.status.ended = true; }), forge(e => { e.transcript.commands.pop(); }), { checkpoint: row.checkpoint, checkpoint_digest: 'f'.repeat(64) }]) {
    await setColumns(f); await assert.rejects(s.view('p1', { matchId: id }), e => ['UNAVAILABLE', 'PIN_UNAVAILABLE'].includes(e?.code)); R.tamper++; await setColumns(row);
  }
  const restored = await s.view('p1', { matchId: id }); assert.equal(enc(restored), enc(good));
  // Forged rows ran fresh projections (or failed before projecting); the restored row is a cache hit with no new projection.
  const afterTamper = projects; await s.view('p1', { matchId: id }); assert.equal(projects, afterTamper); assert.ok(afterTamper >= countBefore);
  // Reference-command semantics at the service boundary.
  const pv = await s.view('p1', { matchId: id }), version = pv.stateVersion;
  const bad = await s2.submitRefs('p1', refCommand('bad-ref', version, 'quest', { cardId: 'vr_' + '0'.repeat(64) }));
  assert.equal(bad.receipt.outcome, 'rejected'); assert.equal(bad.receipt.reason, 'invalid_intent');
  const again = await s2.submitRefs('p1', refCommand('bad-ref', version, 'quest', { cardId: 'vr_' + '0'.repeat(64) })); assert.equal(again.duplicate, true); assert.equal(again.receipt.outcome, 'rejected');
  await assert.rejects(s2.submitRefs('p1', refCommand('bad-ref', version, 'passTurn', {})), e => e?.code === 'ID_CONFLICT'); R.refs.rejectedRetry = 'duplicate rejected; changed payload ID_CONFLICT';
  // The raw (trusted) and reference namespaces never alias: the same command ID and payload under the other path is a conflict, not a duplicate.
  await assert.rejects(s2.submit('p1', command(id, 'ink-1', v3, 'putCardIntoInkwell', { cardId: ref })), e => e?.code === 'ID_CONFLICT');
  await assert.rejects(s2.submitRefs('p1', refCommand('pass-1', v3 + 1, 'passTurn', {})), e => e?.code === 'ID_CONFLICT'); R.refs.namespaces = 'raw and reference IDs conflict both ways';
  // A raw engine identity sent through the reference path is a durable invalid_intent, never an accepted move.
  const rawId = restorePrivateMatch({ archive: row.checkpoint, digest: row.checkpoint_digest }, id); let internal; try { internal = rawId.resolveIntent('p1', 'quest', { cardId: hand(pv, 'p1').cards[0].ref }).cardId; } finally { rawId.dispose(); }
  const rawRef = await s2.submitRefs('p1', refCommand('raw-id', version, 'putCardIntoInkwell', { cardId: internal })); assert.equal(rawRef.receipt.outcome, 'rejected'); R.refs.rawIdentity = 'rejected';
  const nowCounts = await counts(id); assert.equal(nowCounts.stateVersion, version); assert.equal(nowCounts.journal, version);
  // Longer reference-only play: submit cost per command as the transcript grows (each move restores the full transcript).
  let cur = await s.view('p1', { matchId: id }), n = 0;
  while (!cur.ended && n < 60) {
    const actor = cur.turnOwnerId, mine = await s.view(actor, { matchId: id }), h = hand(mine, actor).cards, v = mine.stateVersion;
    const move = h.length && n % 3 === 0 ? ['putCardIntoInkwell', { cardId: h[0].ref }] : ['passTurn', {}];
    const r = await timed(R.timing.submitMs, () => s2.submitRefs(actor, refCommand('long-' + n++, v, ...move)));
    if (r.receipt.outcome !== 'accepted') { const p = await timed(R.timing.submitMs, () => s2.submitRefs(actor, refCommand('long-' + n++, v, 'passTurn', {}))); assert.equal(p.receipt.outcome, 'accepted'); }
    cur = await timed(R.timing.coldMs, () => s.view('p1', { matchId: id }));
  }
  row = await stored(); assert.equal(enc(cur), enc(project(row, 'p1')));
  // Restart with an empty cache reproduces the same committed view.
  s3 = service(); assert.equal(enc(await s3.view('p1', { matchId: id })), enc(cur));
  const events = (() => { const pm = restorePrivateMatch({ archive: row.checkpoint, digest: row.checkpoint_digest }, id); try { return JSON.parse(row.checkpoint).transcript.commands.length; } finally { pm.dispose(); } })();
  const t = R.timing, stat = a => ({ n: a.length, first: a[0], p50: [...a].sort((x, y) => x - y)[a.length >> 1], last: a.at(-1), max: Math.max(...a) });
  console.log(JSON.stringify({ ...R, projections: projects, finalVersion: Number(row.state_version), ended: cur.ended, transcriptCommands: events, timing: { cold: stat(t.coldMs), warm: stat(t.warmMs), submit: stat(t.submitMs) } }));
  console.log('PASS auditor PLAY-03 cache probe: committed views equal the adapter projection; a 48-way warm burst and a 48-way cold burst each use at most one projection, viewers never share entries, outsiders and malformed requests are refused before the cache, commits through another instance are visible at once, more than 64 concurrent reads are refused with a fixed code, re-digested or mis-digested checkpoint forgeries fail closed instead of hitting the cached view and restored bytes hit again; reference commands keep separate durable namespaces from raw submits, retry rejected intents as duplicates, refuse changed payloads, reject raw engine identities, and a restarted service reproduces the view');
} finally { await s.close(); await s2.close(); await s3?.close(); await cleanup(id); }
